<template><div class="catalog-products min-h-screen bg-slate-50 px-4 py-6 sm:py-8"><div class="mx-auto grid max-w-7xl gap-5 lg:grid-cols-[240px_1fr] lg:gap-8"><div class="hidden lg:block"><CategorySidebar :categories="categoryGroups" :selected-category="selectedCategory" :expanded-parent-ids="expandedParentIds" :show-drawer="showFilterDrawer" :show-search="true" :search-query="searchQuery" @select-category="selectCategory" @toggle-parent="toggleParentCategory" @update:show-drawer="showFilterDrawer = $event" @update:search-query="searchQuery = $event" @clear-search="clearSearch"/></div><main><h1 class="mb-5 text-3xl font-black">{{ t('nav.products') }}</h1><TemplateProductCollection :products="products" :mode="templateMode" grid-class="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3" @click="go" @quick-buy="quickBuy"/><ProductQuickBuy v-if="selected" :product="selected" :visible="quickVisible" @update:visible="quickVisible = $event" /></main></div></div></template>
<script setup lang="ts">import { computed, onMounted, onUnmounted, ref } from 'vue'; import { useI18n } from 'vue-i18n'; import { useRouter } from 'vue-router'; import { useProductList } from '../../composables/useProductList'; import { useAppStore } from '../../stores/app'; import TemplateProductCollection from '../components/TemplateProductCollection.vue'; import ProductQuickBuy from '../../components/ProductQuickBuy.vue'; import CategorySidebar from '../../components/CategorySidebar.vue'; const {t}=useI18n(); const router=useRouter(); const app=useAppStore(); const {products,selectedCategory,searchQuery,showFilterDrawer,expandedParentIds,categoryGroups,selectCategory,toggleParentCategory,clearSearch,initialize,cleanup}=useProductList({pageSize:18,homeRouteName:'products'}); const selected=ref<any>(null);const quickVisible=ref(false);const templateMode=computed<'card'|'list'>(()=>app.config?.template_mode==='list'?'list':'card');const go=(s:string)=>router.push(`/products/${s}`);const quickBuy=(p:any)=>{selected.value=p;quickVisible.value=true};onMounted(async()=>{await app.loadConfig();await initialize()});onUnmounted(cleanup)</script>
